// Conway's Game of Life on the 12 QPUs against the ARM1176, in one boot.
//
// Generated by examples/life_pi.py into its build directory: life_config.h
// (sizes, seeds, launch grids) and the PIton launchers life_tile/rows/bits.{c,h}.
//
// 1. arm_naive runs LIFE_GENS generations of the soup: the reference trace
//    (population and hash of every generation) and final grid.
// 2. Every other implementation (three QPU kernels, two more ARM versions)
//    runs the same generations; every generation's trace and the final grid
//    must match the reference exactly. qpu_tile also keeps crops of the grid
//    for the host's animation.
// 3. Timing: LIFE_REPEATS x LIFE_TIMED_GENS generations per implementation,
//    ping-pong buffers, no checks inside the loop; the final grid is checked
//    against arm_naive's after the same number of generations.
// 4. With LIFE_BIG_H: the bit-sliced kernel against the bit-sliced ARM code on
//    a larger torus, checked and timed the same way.
//
// QPU launches run with the ARM caches off, as in every PIton benchmark (the
// launchers' first call allocates through the mailbox, whose buffer is cached
// ARM memory); the ARM code, and the checks that read GPU memory (uncached,
// strongly ordered), run with them on.
#include "rpi.h"
#include "piton_rt.h"
#include "arm_sgemm.h"
#include "life_config.h"
#include "life_arm.h"
#include "life_tile.h"
#include "life_rows.h"
#include "life_bits.h"

#define H LIFE_H
#define W LIFE_W
#define NW (W / 32)
#define CELLS (H * W)
#define WORDS (H * NW)
#define NSNAP (LIFE_GENS / LIFE_SNAP_EVERY + 1)
#define CROP_WORDS (LIFE_CROP * LIFE_CROP / 32)
#define TIMED_TOTAL (LIFE_REPEATS * LIFE_TIMED_GENS)

#if W % 32 || LIFE_CROP % 32 || LIFE_CROP > H || LIFE_CROP > W || LIFE_GENS % LIFE_SNAP_EVERY
#error "W and LIFE_CROP must be multiples of 32, LIFE_CROP <= H, W, LIFE_SNAP_EVERY must divide LIFE_GENS"
#endif
#if LIFE_GENS < 1 || LIFE_TIMED_GENS < 1 || LIFE_REPEATS < 1
#error "generation counts and repeats must be positive"
#endif

#if LIFE_BIG_H
#define BIG_NW (LIFE_BIG_W / 32)
#define BIG_WORDS (LIFE_BIG_H * BIG_NW)
#define BIG_TIMED_TOTAL (LIFE_REPEATS * LIFE_BIG_TIMED_GENS)
#if LIFE_BIG_W % 32 || LIFE_BIG_GENS < 1 || LIFE_BIG_TIMED_GENS < 1
#error "LIFE_BIG_W must be a multiple of 32 and the big generation counts positive"
#endif
#define MAX_NW (BIG_NW > NW ? BIG_NW : NW)
#else
#define MAX_NW NW
#endif

// GPU memory must lie outside the range arm_caches_on() maps cached
// (arm_sgemm.c CACHED_LIMIT), or the ARM would read stale lines of it.
#define LIFE_CACHED_LIMIT 0x08000000u

enum { QPU_TILE, QPU_ROWS, QPU_BITS, ARM_NAIVE, ARM_ROWS, ARM_BITS, NUM_IMPLS };
static const char *const impl_names[NUM_IMPLS] = {
    "qpu_tile", "qpu_rows", "qpu_bits", "arm_naive", "arm_rows", "arm_bits"};

static int is_qpu(int impl) { return impl <= QPU_BITS; }
static int is_words(int impl) { return impl == QPU_BITS || impl == ARM_BITS; }

static int32_t arm_cells[2][CELLS];
static uint32_t arm_words[2][WORDS];
static int32_t cell_scratch[W];
static uint32_t word_scratch[6 * MAX_NW];
static piton_buf_t gpu_cells[2], gpu_words[2];

static uint32_t ref_pop[LIFE_GENS + 1], ref_hash[LIFE_GENS + 1];
static uint32_t run_pop[LIFE_GENS + 1], run_hash[LIFE_GENS + 1];
static uint32_t ref_final[WORDS], qpu_final[WORDS], timed_final[WORDS];
static uint32_t snaps[NSNAP][CROP_WORDS];

#if LIFE_BIG_H
static uint32_t big_words[2][BIG_WORDS];
static piton_buf_t gpu_big[2];
static uint32_t big_ref_pop[LIFE_BIG_GENS + 1], big_ref_hash[LIFE_BIG_GENS + 1];
static uint32_t big_run_pop[LIFE_BIG_GENS + 1], big_run_hash[LIFE_BIG_GENS + 1];
static uint32_t big_final[BIG_WORDS], big_timed_final[BIG_WORDS];
#endif

static unsigned failures;

// One implementation's grid in flight; buffer `cur` holds the current generation.
typedef struct {
    int impl;
    unsigned rows, cols, gx, gy, cur;
    uint32_t seed;
    void *arm[2];           // ARM implementations: cached RAM
    piton_buf_t *gpu;       // QPU implementations: two GPU buffers
} life_t;

static life_t small_grid(int impl) {
    static const unsigned gx[] = {LIFE_TILE_GX, LIFE_ROWS_GX, LIFE_BITS_GX};
    static const unsigned gy[] = {LIFE_TILE_GY, LIFE_ROWS_GY, LIFE_BITS_GY};
    life_t g = { impl, H, W, 0, 0, 0, LIFE_SEED, {0, 0}, 0 };
    if (is_qpu(impl)) {
        g.gx = gx[impl];
        g.gy = gy[impl];
        g.gpu = is_words(impl) ? gpu_words : gpu_cells;
    } else if (is_words(impl)) {
        g.arm[0] = arm_words[0];
        g.arm[1] = arm_words[1];
    } else {
        g.arm[0] = arm_cells[0];
        g.arm[1] = arm_cells[1];
    }
    return g;
}

#if LIFE_BIG_H
static life_t big_grid(int impl) {
    life_t g = { impl, LIFE_BIG_H, LIFE_BIG_W, LIFE_BIG_GX, LIFE_BIG_GY, 0, LIFE_BIG_SEED,
                 {big_words[0], big_words[1]}, gpu_big };
    return g;
}
#endif

static volatile void *buffer(const life_t *g, unsigned which) {
    return is_qpu(g->impl) ? g->gpu[which].cpu : g->arm[which];
}

static void reset(life_t *g) {
    g->cur = 0;
    if (is_words(g->impl))
        life_soup_words(buffer(g, 0), g->rows, g->cols, g->seed, LIFE_EIGHTHS);
    else
        life_soup_cells(buffer(g, 0), g->rows, g->cols, g->seed, LIFE_EIGHTHS);
}

// One generation; returns the QPU launch's own time (0 for the ARM).
static uint32_t step(life_t *g) {
    unsigned src = g->cur, dst = src ^ 1;
    uint32_t us = 0;
    switch (g->impl) {
    case QPU_TILE: {
        life_tile_args_t a = { .src_ptr = g->gpu[src].bus, .dst_ptr = g->gpu[dst].bus,
                               .n_rows = g->rows, .n_cols = g->cols, .stride = g->cols };
        us = life_tile_launch(&a, g->gx, g->gy, 1);
        break;
    }
    case QPU_ROWS: {
        life_rows_args_t a = { .src_ptr = g->gpu[src].bus, .dst_ptr = g->gpu[dst].bus,
                               .n_rows = g->rows, .n_cols = g->cols, .stride = g->cols };
        us = life_rows_launch(&a, g->gx, g->gy, 1);
        break;
    }
    case QPU_BITS: {
        life_bits_args_t a = { .src_ptr = g->gpu[src].bus, .dst_ptr = g->gpu[dst].bus,
                               .n_rows = g->rows, .n_words = g->cols >> 5, .stride = g->cols >> 5 };
        us = life_bits_launch(&a, g->gx, g->gy, 1);
        break;
    }
    case ARM_NAIVE:
        life_arm_naive(g->arm[src], g->arm[dst], g->rows, g->cols);
        break;
    case ARM_ROWS:
        life_arm_rows(g->arm[src], g->arm[dst], g->rows, g->cols, cell_scratch);
        break;
    case ARM_BITS:
        life_arm_bits(g->arm[src], g->arm[dst], g->rows, g->cols, word_scratch);
        break;
    }
    g->cur = dst;
    return us;
}

static life_trace_t grid_trace(const life_t *g) {
    volatile const void *p = buffer(g, g->cur);
    return is_words(g->impl) ? life_trace_words(p, g->rows, g->cols)
                             : life_trace_cells(p, g->rows, g->cols);
}

static void pack_current(const life_t *g, uint32_t *out) {
    volatile const void *p = buffer(g, g->cur);
    unsigned n = g->rows * (g->cols >> 5);
    if (is_words(g->impl)) {
        volatile const uint32_t *w = p;
        for (unsigned i = 0; i < n; i++)
            out[i] = w[i];
    } else {
        life_pack(p, out, g->rows, g->cols);
    }
}

static unsigned diff_current(const life_t *g, const uint32_t *ref) {
    volatile const void *p = buffer(g, g->cur);
    return is_words(g->impl) ? life_diff_words(p, ref, g->rows, g->cols)
                             : life_diff_cells(p, ref, g->rows, g->cols);
}

// A QPU step needs the ARM caches off; the caller has them on.
static uint32_t step_cached(life_t *g) {
    if (!is_qpu(g->impl))
        return step(g);
    arm_caches_off();
    uint32_t us = step(g);
    arm_caches_on();
    return us;
}

static void print_trace(const life_t *g, const uint32_t *pop, const uint32_t *hash, unsigned gens) {
    printk("LIFE_TRACE impl=%s size=%dx%d gens=%d\n", impl_names[g->impl], g->rows, g->cols, gens);
    for (unsigned i = 0; i <= gens; i++)
        printk(i % 8 == 7 || i == gens ? "%d:%x\n" : "%d:%x ", pop[i], hash[i]);
    printk("LIFE_TRACE_END\n");
}

// The custom base-64 of the host decoder (life_pi.py decode_words): no
// upper-case letters, so a dump can never contain PANIC or PITON_DONE.
static void print_words(const uint32_t *words, unsigned n) {
    static const char alphabet[] =
        "0123456789abcdefghijklmnopqrstuvwxyz!#$%&()*+,-./:;<=>?@[]^_{|}~";
    char line[65];
    unsigned bytes = 4 * n, used = 0;
    for (unsigned i = 0; i < bytes; i += 3) {
        uint32_t v = 0, k = bytes - i < 3 ? bytes - i : 3;
        for (unsigned j = 0; j < k; j++)
            v |= ((words[(i + j) >> 2] >> (8 * ((i + j) & 3))) & 0xffu) << (8 * j);
        for (unsigned j = 0; j <= k; j++) {
            line[used++] = alphabet[(v >> (6 * j)) & 63];
            if (used == 64) {
                line[used] = 0;
                printk("%s\n", line);
                used = 0;
            }
        }
    }
    if (used) {
        line[used] = 0;
        printk("%s\n", line);
    }
}

// Runs `gens` generations from the soup, tracing every one; returns the bad cells.
static unsigned run_traced(life_t *g, unsigned gens, uint32_t *pop, uint32_t *hash, int snapshots) {
    unsigned bad = 0;
    reset(g);
    life_trace_t t = grid_trace(g);
    pop[0] = t.pop;
    hash[0] = t.hash;
    bad += t.bad;
    if (snapshots)
        life_crop_cells(buffer(g, g->cur), g->cols, LIFE_CROP, snaps[0]);
    for (unsigned gen = 1; gen <= gens; gen++) {
        step_cached(g);
        t = grid_trace(g);
        pop[gen] = t.pop;
        hash[gen] = t.hash;
        bad += t.bad;
        if (snapshots && gen % LIFE_SNAP_EVERY == 0)
            life_crop_cells(buffer(g, g->cur), g->cols, LIFE_CROP, snaps[gen / LIFE_SNAP_EVERY]);
    }
    return bad;
}

static void validate(life_t *g, unsigned gens, const uint32_t *rpop, const uint32_t *rhash,
                     const uint32_t *rfinal, uint32_t *pop, uint32_t *hash, int snapshots) {
    uint32_t start = timer_get_usec();
    unsigned bad = run_traced(g, gens, pop, hash, snapshots);
    unsigned trace_mismatch = 0;
    for (unsigned i = 0; i <= gens; i++)
        trace_mismatch += pop[i] != rpop[i] || hash[i] != rhash[i];
    unsigned cells = diff_current(g, rfinal);
    uint32_t elapsed = timer_get_usec() - start;
    print_trace(g, pop, hash, gens);
    printk("LIFE_VALIDATE impl=%s size=%dx%d gens=%d trace_mismatch=%d cell_mismatch=%d bad=%d us=%d\n",
           impl_names[g->impl], g->rows, g->cols, gens, trace_mismatch, cells, bad, elapsed);
    failures += trace_mismatch + cells + bad;
}

// The reference: `gens` traced generations, final grid packed into `final`.
static void reference(life_t *g, unsigned gens, uint32_t *pop, uint32_t *hash, uint32_t *final) {
    uint32_t start = timer_get_usec();
    unsigned bad = run_traced(g, gens, pop, hash, 0);
    pack_current(g, final);
    uint32_t elapsed = timer_get_usec() - start;
    print_trace(g, pop, hash, gens);
    printk("LIFE_VALIDATE impl=%s size=%dx%d gens=%d trace_mismatch=0 cell_mismatch=0 bad=%d us=%d reference=1\n",
           impl_names[g->impl], g->rows, g->cols, gens, bad, elapsed);
    failures += bad;
}

// LIFE_REPEATS timed runs of `gens` generations, continuing from one to the
// next; the grid after all of them is compared with `ref` (or stored into it).
static void time_runs(life_t *g, unsigned gens, uint32_t *ref, int store) {
    uint32_t total_us[LIFE_REPEATS], launch_us[LIFE_REPEATS];
    reset(g);
    if (is_qpu(g->impl))
        arm_caches_off();
    for (unsigned r = 0; r < LIFE_REPEATS; r++) {
        uint32_t launches = 0, start = timer_get_usec();
        for (unsigned i = 0; i < gens; i++)
            launches += step(g);
        total_us[r] = timer_get_usec() - start;
        launch_us[r] = launches;
    }
    if (is_qpu(g->impl))
        arm_caches_on();
    for (unsigned r = 0; r < LIFE_REPEATS; r++)
        printk("LIFE_TIME impl=%s size=%dx%d gens=%d us=%d launch_us=%d\n",
               impl_names[g->impl], g->rows, g->cols, gens, total_us[r], launch_us[r]);
    life_trace_t t = grid_trace(g);
    unsigned cells = 0;
    if (store)
        pack_current(g, ref);
    else
        cells = diff_current(g, ref);
    printk("LIFE_TIMED_CHECK impl=%s size=%dx%d gens=%d pop=%d hash=%x cell_mismatch=%d bad=%d\n",
           impl_names[g->impl], g->rows, g->cols, LIFE_REPEATS * gens, t.pop, t.hash, cells, t.bad);
    failures += cells + t.bad;
}

static void check_gpu_buffer(const char *name, const piton_buf_t *b) {
#ifndef LIFE_HOST
    if ((uint32_t)b->cpu < LIFE_CACHED_LIMIT) {
        printk("LIFE_FATAL GPU buffer %s at %x is inside the ARM's cached range\n", name, (uint32_t)b->cpu);
        printk("LIFE_CHECK_FAILED\nPITON_DONE\n");
        clean_reboot();
    }
#endif
}

void notmain(void) {
    piton_init();
    printk("PIton Game of Life: %dx%d torus, %d QPUs\n", H, W, piton_qpu_count());
    printk("LIFE_CONFIG rows=%d cols=%d seed=%d eighths=%d gens=%d timed_gens=%d repeats=%d "
           "snap_every=%d crop=%d big_rows=%d big_cols=%d big_seed=%d big_gens=%d big_timed_gens=%d\n",
           H, W, LIFE_SEED, LIFE_EIGHTHS, LIFE_GENS, LIFE_TIMED_GENS, LIFE_REPEATS, LIFE_SNAP_EVERY,
           LIFE_CROP, LIFE_BIG_H, LIFE_BIG_W, LIFE_BIG_SEED, LIFE_BIG_GENS, LIFE_BIG_TIMED_GENS);
    static const unsigned clocks[] = {PITON_CLOCK_ARM, PITON_CLOCK_CORE, PITON_CLOCK_V3D, PITON_CLOCK_SDRAM};
    static const char *const clock_names[] = {"arm", "core", "v3d", "sdram"};
    for (unsigned i = 0; i < 4; i++)
        printk("LIFE_CLOCK name=%s mhz=%d\n", clock_names[i], piton_clock_hz(clocks[i], 0) / 1000000);

    // All allocation (mailbox) happens here, with the ARM caches off: the
    // buffers, and each launcher's code and uniforms in a first launch on the
    // largest grid it will see.
    uint32_t setup_start = timer_get_usec();
    for (unsigned i = 0; i < 2; i++) {
        gpu_cells[i] = piton_alloc(CELLS * 4);
        gpu_words[i] = piton_alloc(WORDS * 4);
        check_gpu_buffer("cells", &gpu_cells[i]);
        check_gpu_buffer("words", &gpu_words[i]);
#if LIFE_BIG_H
        gpu_big[i] = piton_alloc(BIG_WORDS * 4);
        check_gpu_buffer("big", &gpu_big[i]);
#endif
    }
#if LIFE_BIG_H
    life_t warm_big = big_grid(QPU_BITS);
    reset(&warm_big);
    step(&warm_big);
#endif
    for (int impl = QPU_TILE; impl <= QPU_BITS; impl++) {
        life_t warm = small_grid(impl);
        reset(&warm);
        step(&warm);
    }
    printk("LIFE_SETUP us=%d\n", timer_get_usec() - setup_start);

    arm_caches_on();
    life_t ref = small_grid(ARM_NAIVE);
    reference(&ref, LIFE_GENS, ref_pop, ref_hash, ref_final);
    static const int checked[] = {QPU_TILE, QPU_ROWS, QPU_BITS, ARM_ROWS, ARM_BITS};
    for (unsigned i = 0; i < sizeof(checked) / sizeof(checked[0]); i++) {
        life_t g = small_grid(checked[i]);
        validate(&g, LIFE_GENS, ref_pop, ref_hash, ref_final, run_pop, run_hash, checked[i] == QPU_TILE);
        if (checked[i] == QPU_TILE)
            pack_current(&g, qpu_final);
    }

    // timing: arm_naive first, its final grid is the others' reference
    static const int timed[] = {ARM_NAIVE, ARM_ROWS, ARM_BITS, QPU_TILE, QPU_ROWS, QPU_BITS};
    for (unsigned i = 0; i < sizeof(timed) / sizeof(timed[0]); i++) {
        life_t g = small_grid(timed[i]);
        time_runs(&g, LIFE_TIMED_GENS, timed_final, timed[i] == ARM_NAIVE);
    }

#if LIFE_BIG_H
    life_t big_ref = big_grid(ARM_BITS), big_qpu = big_grid(QPU_BITS);
    reference(&big_ref, LIFE_BIG_GENS, big_ref_pop, big_ref_hash, big_final);
    validate(&big_qpu, LIFE_BIG_GENS, big_ref_pop, big_ref_hash, big_final, big_run_pop, big_run_hash, 0);
    time_runs(&big_ref, LIFE_BIG_TIMED_GENS, big_timed_final, 1);
    time_runs(&big_qpu, LIFE_BIG_TIMED_GENS, big_timed_final, 0);
#endif
    arm_caches_off();

    printk("LIFE_SNAPS impl=qpu_tile size=%dx%d crop=%d every=%d count=%d\n",
           H, W, LIFE_CROP, LIFE_SNAP_EVERY, NSNAP);
    for (unsigned i = 0; i < NSNAP; i++) {
        printk("LIFE_SNAP gen=%d\n", i * LIFE_SNAP_EVERY);
        print_words(snaps[i], CROP_WORDS);
    }
    printk("LIFE_SNAPS_END\n");
    printk("LIFE_FINAL impl=qpu_tile size=%dx%d gen=%d words=%d\n", H, W, LIFE_GENS, WORDS);
    print_words(qpu_final, WORDS);
    printk("LIFE_FINAL_END\n");
    printk(failures ? "LIFE_CHECK_FAILED\n" : "LIFE_CHECK_OK\n");
    printk("PITON_DONE\n");
}
